import json, pandas as pd, numpy as np
facts=json.load(open('facts.json'))
for f in facts:
    print('='*20, f['id'])
    env={'pd':pd,'np':np}
    for k,p in f['tables'].items():
        env[k]=pd.read_csv(p)
    try:
        out=eval(f['code'], env)
        print(out)
    except Exception as e:
        print('ERROR', type(e).__name__, e)
    print()
"

